/**
 * 串口通信手布：STM32F103C8 QFP-48 + 晶振/复位/电源 LED + UART 排针。
 * Cu=4：In1=GND / In2=VCC；信号短走 F/B，禁止再走自动布线乱板。
 */
function handLayoutLabUart(doc) {
  doc.tracks = [];
  doc.vias = [];
  doc.zones = [];
  doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);

  for (const fp of doc.footprints) {
    if (fp.refDes === 'U1') {
      const neu = instantiate('FP_QFP48', 'U1', fp.value || 'STM32F103C8', fp.position, 0, fp.schematicCompId);
      fp.defId = neu.defId;
      fp.pads = neu.pads;
      for (const pad of fp.pads) { pad.netId = undefined; pad.netName = undefined; }
    } else if (fp.refDes === 'Y1' && fp.defId !== 'FP_HC49') {
      const neu = instantiate('FP_HC49', 'Y1', fp.value || '8M', fp.position, 0, fp.schematicCompId);
      fp.defId = neu.defId;
      fp.pads = neu.pads;
      for (const pad of fp.pads) { pad.netId = undefined; pad.netName = undefined; }
    }
  }

  const byRef = new Map(doc.footprints.map(f => [f.refDes, f]));
  const setPos = (ref, x, y, rot = 0) => {
    const fp = byRef.get(ref);
    if (!fp) return;
    fp.position = { x, y };
    fp.rotation = rot;
    fp.mirrored = false;
    fp.layer = 'F.Cu';
  };

  const gnd = doc.nets.find(n => isGndNet(n.name));
  const netByName = (name) => doc.nets.find(n => (n.name || '').toUpperCase() === name);
  const vcc = netByName('VCC');
  const xtal1 = netByName('XTAL1');
  const xtal2 = netByName('XTAL2');
  const nrst = netByName('NRST');
  const uartTx = netByName('UART_TX');
  const uartRx = netByName('UART_RX');
  const pwrLed = netByName('PWR_LED');

  const ux = 800, uy = 800;
  const j1x = 1500;
  setPos('U1', ux, uy, 0);
  setPos('Y1', ux, 1280, 0);
  setPos('CX1', ux - 160, 1420, 0);
  setPos('CX2', ux + 160, 1420, 0);
  setPos('R1', 300, 820, 0);           // 左：NRST 上拉，远离 QFP 左边
  setPos('C3', 1250, 480, 0);           // 右上退耦，避开 QFP 本体
  setPos('R_PWR', 1250, 200, 0);
  setPos('D1', 1410, 200, 0);

  const hdr = instantiate('FP_PINHDR_4', 'J1', 'UART', { x: j1x, y: uy }, 0);
  const hdrNets = [gnd, vcc, uartTx, uartRx];
  for (let i = 0; i < hdr.pads.length; i++) {
    const n = hdrNets[i];
    if (!n) continue;
    hdr.pads[i].netId = n.id;
    hdr.pads[i].netName = n.name;
  }
  doc.footprints.push(hdr);

  const bindPad = (ref, num, net) => {
    const fp = byRef.get(ref) || doc.footprints.find(f => f.refDes === ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    if (pad && net) { pad.netId = net.id; pad.netName = net.name; }
  };
  // MCU 电源多焊盘同网
  for (const n of ['8', '23', '35', '47']) bindPad('U1', n, gnd);
  for (const n of ['9', '24', '36', '48']) bindPad('U1', n, vcc);
  bindPad('U1', '5', xtal1);
  bindPad('U1', '6', xtal2);
  bindPad('U1', '7', nrst);
  bindPad('U1', '30', uartTx);
  bindPad('U1', '31', uartRx);
  bindPad('Y1', '1', xtal1);
  bindPad('Y1', '2', xtal2);
  bindPad('CX1', '1', xtal1); bindPad('CX1', '2', gnd);
  bindPad('CX2', '1', xtal2); bindPad('CX2', '2', gnd);
  bindPad('R1', '1', nrst); bindPad('R1', '2', vcc);
  bindPad('C3', '1', vcc); bindPad('C3', '2', gnd);
  bindPad('R_PWR', '1', vcc); bindPad('R_PWR', '2', pwrLed);
  bindPad('D1', '1', pwrLed); bindPad('D1', '2', gnd); // A/K via LED pad numbers 1/2 after annotate — check
  // LED_GREEN pads may be A/K mapped to 1/2 by lookup; hand-bind by net from sch: A=PWR_LED K=GND
  {
    const d1 = byRef.get('D1');
    if (d1) {
      for (const pad of d1.pads) {
        if (pad.number === '1' || (pad.netName || '').toUpperCase() === 'A') {
          pad.netId = pwrLed?.id; pad.netName = pwrLed?.name; pad.number = '1';
        }
        if (pad.number === '2' || (pad.netName || '').toUpperCase() === 'K') {
          pad.netId = gnd?.id; pad.netName = gnd?.name;
        }
      }
      // 0805: pad1 left, pad2 right — A on 1, K on 2
      const p1 = d1.pads.find(p => p.number === '1');
      const p2 = d1.pads.find(p => p.number === '2');
      if (p1 && pwrLed) { p1.netId = pwrLed.id; p1.netName = pwrLed.name; }
      if (p2 && gnd) { p2.netId = gnd.id; p2.netName = gnd.name; }
    }
  }

  const pw = (ref, num) => {
    const fp = doc.footprints.find(f => f.refDes === ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    return padWorld(fp, pad);
  };
  const add = (net, a, b, w = 12, layer = 'F.Cu') => {
    if (!net || !a || !b || dist(a, b) < 0.5) return;
    doc.tracks.push({
      id: uid('trk'), layer,
      start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
      width: w, netId: net.id, netName: net.name
    });
  };
  const viaLayers = ['F.Cu', 'In1.Cu', 'In2.Cu', 'B.Cu'];
  const addVia = (net, p) => {
    if (!net || !p) return;
    for (const v of doc.vias) {
      if (v.netId === net.id && Math.abs(v.position.x - p.x) < 0.5 &&
        Math.abs(v.position.y - p.y) < 0.5) return;
    }
    doc.vias.push({
      id: uid('via'), position: { x: p.x, y: p.y },
      drill: 12, diameter: 24,
      netId: net.id, netName: net.name,
      layers: [...viaLayers], kind: 'through'
    });
  };
  const toInner = (net, padPt, dx, dy, _inner, w = 14) => {
    const e = { x: padPt.x + dx, y: padPt.y + dy };
    add(net, padPt, e, w, 'F.Cu');
    addVia(net, e);
    return e;
  };

  const uOscIn = pw('U1', 5), uOscOut = pw('U1', 6), uRst = pw('U1', 7);
  const uTx = pw('U1', 30), uRx = pw('U1', 31);
  const uVdd = pw('U1', 24), uVss = pw('U1', 23);
  const yA = pw('Y1', 1), yB = pw('Y1', 2);
  const cx1a = pw('CX1', 1), cx1b = pw('CX1', 2);
  const cx2a = pw('CX2', 1), cx2b = pw('CX2', 2);
  const r1a = pw('R1', 1), r1b = pw('R1', 2);
  const c3a = pw('C3', 1), c3b = pw('C3', 2);
  const rpA = pw('R_PWR', 1), rpB = pw('R_PWR', 2);
  const dA = pw('D1', 1), dK = pw('D1', 2);
  const jGnd = pw('J1', 1), jVcc = pw('J1', 2), jTx = pw('J1', 3), jRx = pw('J1', 4);

  // 电源：多 VDD/VSS 过孔进内电层
  addVia(vcc, uVdd);
  addVia(gnd, uVss);
  addVia(vcc, pw('U1', 9));
  addVia(vcc, pw('U1', 36));
  addVia(vcc, pw('U1', 48));
  addVia(gnd, pw('U1', 8));
  addVia(gnd, pw('U1', 35));
  addVia(gnd, pw('U1', 47));
  toInner(vcc, c3a, 0, -50, 'In2.Cu', 14);
  toInner(gnd, c3b, 0, 50, 'In1.Cu', 14);
  toInner(vcc, r1b, -45, 0, 'In2.Cu', 14);
  toInner(vcc, rpA, 0, -45, 'In2.Cu', 14);
  toInner(gnd, dK, 0, 50, 'In1.Cu', 14);
  addVia(gnd, jGnd);
  addVia(vcc, jVcc);

  // 复位：R1.1 — F 短连 NRST
  add(nrst, r1a, uRst, 12, 'F.Cu');

  // 晶振：XTAL1 走 F 左列；XTAL2 走 B，避免共列
  const col1 = uOscIn.x - 100;
  add(xtal1, uOscIn, { x: col1, y: uOscIn.y }, 12, 'F.Cu');
  add(xtal1, { x: col1, y: uOscIn.y }, { x: col1, y: yA.y }, 12, 'F.Cu');
  add(xtal1, { x: col1, y: yA.y }, yA, 12, 'F.Cu');
  add(xtal1, yA, { x: yA.x, y: cx1a.y }, 12, 'F.Cu');
  add(xtal1, { x: yA.x, y: cx1a.y }, cx1a, 12, 'F.Cu');
  const eX2 = { x: uOscOut.x - 55, y: uOscOut.y };
  add(xtal2, uOscOut, eX2, 12, 'F.Cu');
  addVia(xtal2, eX2);
  const x2Bot = cx2a.y + 60;
  add(xtal2, eX2, { x: eX2.x, y: x2Bot }, 12, 'B.Cu');
  add(xtal2, { x: eX2.x, y: x2Bot }, { x: yB.x, y: x2Bot }, 12, 'B.Cu');
  add(xtal2, { x: yB.x, y: x2Bot }, yB, 12, 'B.Cu');
  add(xtal2, yB, { x: yB.x, y: cx2a.y }, 12, 'B.Cu');
  add(xtal2, { x: yB.x, y: cx2a.y }, { x: cx2a.x, y: cx2a.y }, 12, 'B.Cu');
  addVia(xtal2, { x: cx2a.x, y: cx2a.y });
  add(xtal2, { x: cx2a.x, y: cx2a.y }, cx2a, 12, 'F.Cu');
  toInner(gnd, cx1b, 0, 55, 'In1.Cu', 14);
  toInner(gnd, cx2b, 0, 55, 'In1.Cu', 14);

  // 电源 LED
  add(pwrLed, rpB, dA, 12, 'F.Cu');

  // UART：右侧专属列上 B → 排针（TX/RX 分行）
  const eTx = { x: uTx.x + 55, y: uTx.y };
  add(uartTx, uTx, eTx, 12, 'F.Cu');
  addVia(uartTx, eTx);
  {
    const col = j1x - 80;
    add(uartTx, eTx, { x: col, y: eTx.y }, 12, 'B.Cu');
    add(uartTx, { x: col, y: eTx.y }, { x: col, y: jTx.y }, 12, 'B.Cu');
    add(uartTx, { x: col, y: jTx.y }, jTx, 12, 'B.Cu');
  }
  const eRx = { x: uRx.x + 55, y: uRx.y };
  add(uartRx, uRx, eRx, 12, 'F.Cu');
  addVia(uartRx, eRx);
  {
    const col = j1x + 80;
    add(uartRx, eRx, { x: col, y: eRx.y }, 12, 'B.Cu');
    add(uartRx, { x: col, y: eRx.y }, { x: col, y: jRx.y }, 12, 'B.Cu');
    add(uartRx, { x: col, y: jRx.y }, jRx, 12, 'B.Cu');
  }

  return {
    trackCount: doc.tracks.length,
    netCount: [vcc, gnd, xtal1, xtal2, nrst, uartTx, uartRx, pwrLed].filter(Boolean).length,
    viaCount: doc.vias.length
  };
}

